#!/usr/bin/env python3
"""Redewendungen: drei neue Filter - Lehnwoerter (8), Scheinenglisch (5), Wortfamilien (11). Alle Herkunftsangaben nach DWDS geprueft. Idempotent."""
import os,json
from urllib.parse import quote
root=os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
p=os.path.join(root,"index.html");s=open(p,encoding="utf-8").read()
if '["lehn","A2","das Fenster"' in s: print("already");raise SystemExit
def row(k,l,w,e,en,x,h,slug):
    for t in (w,e,en,x,h or ''): assert '"' not in t,t
    return '["%s","%s","%s","%s","%s","%s",%s,%s]'%(k,l,w,e,en,x,json.dumps(h,ensure_ascii=False) if h else 'null',json.dumps(["https://www.dwds.de/wb/"+quote(slug),"DWDS"],ensure_ascii=False) if h else 'null')
R=[
("lehn","A2","das Fenster","die Öffnung in der Wand mit Glas","window (from Latin)","Mach bitte das Fenster zu, es zieht.","Aus lateinisch fenestra, „Öffnung, Luke in der Wand“, vielleicht etruskischen Ursprungs. Im 8. Jahrhundert tauchen erste Formen auf, althochdeutsch fenstar um das Jahr 1000.","Fenster"),
("lehn","A1","die Straße","ein befestigter Weg für Fahrzeuge und Fußgänger","street, road (from Latin)","Die Straße vor dem Haus ist gesperrt.","Aus spätlateinisch via strāta, dem gepflasterten Weg (zu sternere, ausbreiten, pflastern). Im 8. Jahrhundert althochdeutsch strāʒa, zuerst für die Heerstraße, später auch die Stadtstraße.","Straße"),
("lehn","A1","der Wein","das Getränk aus vergorenem Traubensaft","wine (from Latin)","Zum Fisch trinke ich gern einen Weißwein.","Aus lateinisch vīnum, schon früh entlehnt. Althochdeutsch wīn ist um 800 belegt.","Wein"),
("lehn","B1","der Kaiser","der höchste Herrscher eines Kaiserreichs","emperor (from the name Caesar)","Franz Joseph war Kaiser von Österreich.","Aus dem Familiennamen Caesar, mit dem Gaius Iulius Caesar gemeint ist. Im Römischen Reich wurde der Name zum Herrschertitel; die Germanen übernahmen ihn früh, vielleicht schon zu Caesars Lebzeiten. Althochdeutsch keisur um 800.","Kaiser"),
("lehn","B1","die Mauer","die feste Wand aus Stein oder Ziegeln, oft im Freien","wall (from Latin)","Um den Garten steht eine hohe Mauer.","Aus lateinisch mūrus. Die Germanen übernahmen das Wort, als sie den römischen Steinbau kennenlernten. Im 8. Jahrhundert belegt. Das weibliche Geschlecht kommt von Wand.","Mauer"),
("lehn","A2","das Büro","der Arbeitsraum für Schreibarbeit und Verwaltung","office (from French)","Morgen bin ich den ganzen Tag im Büro.","Aus französisch bureau, „Amtszimmer“. Das Wort geht auf einen groben Wollstoff zurück, mit dem man Schreibtische bedeckte; dann hieß der Tisch so und schließlich der Raum. 1695 vereinzelt im Deutschen, im späten 18. Jahrhundert üblich. Die Schreibung Büro gibt es erst nach 1920.","Büro"),
("lehn","A2","die Garage","der Raum oder das Gebäude für ein Auto","garage (from French)","Das Auto steht in der Garage.","Aus französisch garage, zum Verb garer, „unterstellen“. Anfang des 20. Jahrhunderts ins Deutsche gekommen.","Garage"),
("lehn","A1","der Kaffee","das Getränk aus gerösteten Kaffeebohnen","coffee (an Arabic word that travelled)","Ich trinke morgens immer einen Kaffee.","Vom arabischen qahwa über das Türkische (kahve) nach Westeuropa. Im 17. Jahrhundert kam das Wort über französisch café und englisch coffee ins Deutsche; um 1670 wurde das Getränk bei uns eingeführt.","Kaffee"),
("schein","A2","das Handy","das Mobiltelefon","mobile phone (in English: mobile or cell phone)","Hast du dein Handy dabei?","Englisch klingt es, ist aber kein englisches Wort für das Telefon. Seit etwa 1986 ist Handy in Deutschland üblich. Wahrscheinlich geht es auf das amerikanische Handie-Talkie zurück, ein tragbares Funkgerät um 1940. Um 1990 deutete man es als Hand + -y: etwas, das immer zur Hand ist.","Handy"),
("schein","B1","der Beamer","das Gerät, das ein Bild an die Wand projiziert","projector (English: projector)","Der Beamer in Raum 3 ist kaputt.","Von englisch beam, Strahl, und to beam, strahlen. DWDS nennt das Wort einen Scheinanglizismus: Es sieht englisch aus, heißt im Englischen aber nicht so.","Beamer"),
("schein","B1","der Oldtimer","ein altes, gepflegtes Fahrzeug von Wert","vintage car (English: old-timer is a person)","Am Sonntag fuhr ein Oldtimer durch das Dorf.","Aus amerikanisch old-timer, einem älteren Menschen oder Veteranen. Im Deutschen meint das Wort vor allem ein altes Sammlerstück, besonders ein Auto; im Scherz auch einen älteren, geachteten Menschen.","Oldtimer"),
("schein","B2","der Smoking","der festliche schwarze Abendanzug","dinner jacket (tuxedo in the US)","Zur Gala muss man im Smoking kommen.","Kurzform von englisch smoking jacket aus dem 19. Jahrhundert, einer Rauchjacke, die man nach dem Essen statt des Fracks trug. Im Englischen sagt man meist dinner jacket.","Smoking"),
("schein","C1","der Twen","ein Mensch zwischen 20 und 30","someone in their twenties","Der Film richtet sich an Twens.","Eine englisch klingende Bildung zu twenty aus dem 20. Jahrhundert, nach dem Muster von teen wie in Teenager.","Twen"),
("fam","A2","fahren – Fähre, Fuhre, erfahren","eine Wortfamilie: Diese Wörter gehören zusammen, auch wenn man es nicht sofort hört","family of fahren (to travel, drive)","Fähre, Fuhre und erfahren haben dieselbe Wurzel wie fahren. Gefahr gehört nicht dazu.",None,None),
("fam","B1","die Fähre","das Schiff, das Menschen und Fahrzeuge über das Wasser bringt","ferry","Die Fähre fährt jede halbe Stunde.","Eng mit fahren verwandt: Das germanische Wort bedeutete etwa „ein Fahrzeug zum Übersetzen“, gebildet zu einem Verb mit der Bedeutung „über das Wasser fahren lassen“. Das Verb gibt es im Neuhochdeutschen nicht mehr. Fährmann ist seit dem 17. Jahrhundert belegt.","Fähre"),
("fam","B2","die Fuhre","die Ladung eines Wagens oder die Fahrt damit","a cartload, a haul","Er brachte drei Fuhren Holz.","Zu fahren gebildet. Althochdeutsch fuora im 9. Jahrhundert, ursprünglich allgemeiner: Reise, Weg, Fahrt, Last. Daraus entwickelte sich der Sinn „Fahrt mit Wagen, Wagenladung“.","Fuhre"),
("fam","B2","erfahren / die Erfahrung","etwas durch Dabeisein kennenlernen","to experience; experience","Sie hat viel Erfahrung mit Pferden.","Von fahren gebildet. Althochdeutsch irfaran um 800 hieß ursprünglich durchreisen, durchziehen oder erreichen. Daraus wurde „kennenlernen, erforschen“. Mittelhochdeutsch ervarunge bedeutete noch „Durchfahren, Erkundung“.","erfahren"),
("fam","B2","die Gefahr","die Möglichkeit, dass etwas Schlimmes passiert","danger (not related to fahren)","Es besteht keine Gefahr.","Achtung: Gefahr hat nichts mit fahren zu tun. Mittelhochdeutsch gevāre hieß „Hinterlist, Betrug“ und gehört zu althochdeutsch fāra, „Nachstellung, Versuchung“. Beide stehen mit einer Wurzel „versuchen, wagen“ in Verbindung.","Gefahr"),
("fam","B1","binden – Bund, Bündnis","eine Wortfamilie: etwas, das zusammengebunden oder verbunden ist","family of binden (to bind, tie)","Bund und Bündnis kommen von binden.",None,None),
("fam","B1","der Bund","der Zusammenschluss; oder ein zusammengebundenes Bündel","union, alliance; a bundle","Zwei Bund Stroh liegen im Stall.","Eine ablautende Bildung zu binden. Ursprünglich ein „Büschel, Vereinigung“, althochdeutsch gibunt im 10. und 11. Jahrhundert. Erst im 18. Jahrhundert trennen sich zwei Geschlechter: das Bund (Gebundenes, wie Schlüsselbund) und der Bund (Bündnis, wie Staatenbund).","Bund"),
("fam","B2","das Bündnis","das Abkommen und der Zusammenschluss zu einem gemeinsamen Ziel","alliance, pact","Die Parteien schlossen ein Bündnis.","Von Bund mit der Endung -nis gebildet. Mittelhochdeutsch büntnisse bedeutete „Vertrag, Vereinbarung“.","Bündnis"),
("fam","B1","fallen – Zufall, Unfall","eine Wortfamilie: Was einem zufällt oder unglücklich widerfährt","family of fallen (to fall)","Zufall und Unfall gehören zu fallen.",None,None),
("fam","B1","der Zufall","ein Ereignis, das niemand geplant hat","chance, coincidence","Wir trafen uns durch Zufall im Zug.","Ein Substantiv zum Verb zufallen. Mittelhochdeutsch zuoval hieß etwa Angriff oder Zuteilung. Im 16. Jahrhundert bereitet sich die heutige Bedeutung vor, im 17. Jahrhundert ist sie geläufig.","Zufall"),
("fam","B1","der Unfall","ein plötzliches Ereignis mit Schaden oder Verletzung","accident","Auf der Autobahn gab es einen Unfall.","Aus un- und Fall. Mittelhochdeutsch unval meinte ein Missgeschick, ein unvorhersehbares Unglück. Im Mittelniederdeutschen steht daneben geval ohne Vorsilbe: „Zufall, Glück“.","Unfall"),
]
rows=''.join(','+row('%s'%r[0],*r[1:]) for r in R)
j=s.index('];',s.index('"wort","B1","die Angst"'))
s=s[:j]+rows+s[j:]
a='["wort", "Wörter mit Geschichte"]];'
assert s.count(a)==1
s=s.replace(a,'["wort", "Wörter mit Geschichte"], ["lehn", "Lehnwörter"], ["schein", "Scheinenglisch (Scheinanglizismen)"], ["fam", "Wortfamilien"]];')
open(p,'w',encoding='utf-8').write(s);print('ok',len(R))
